7	import type {
8	  Message,
9	  Part,
10	  TextPart,
11	  DataPart,
12	  FilePart,
13	  Artifact,
14	  TaskState,
15	  TaskStatusUpdateEvent,
16	} from '@a2a-js/sdk';
17	import type { SendMessageResult } from './a2a-client-manager.js';
18	
19	export const AUTH_REQUIRED_MSG = `[Authorization Required] The agent has indicated it requires authorization to proceed. Please follow the agent's instructions.`;
20	
21	/**
22	 * Reassembles incremental A2A streaming updates into a coherent result.
23	 * Shows sequential status/messages followed by all reassembled artifacts.
24	 */
25	export class A2AResultReassembler {
26	  private messageLog: string[] = [];
27	  private artifacts = new Map<string, Artifact>();
28	  private artifactChunks = new Map<string, string[]>();
29	
30	  /**
31	   * Processes a new chunk from the A2A stream.
32	   */
33	  update(chunk: SendMessageResult) {
34	    if (!('kind' in chunk)) return;
35	
36	    switch (chunk.kind) {
37	      case 'status-update':
38	        this.appendStateInstructions(chunk.status?.state);
39	        this.pushMessage(chunk.status?.message);
40	        break;
41	
42	      case 'artifact-update':
43	        if (chunk.artifact) {
44	          const id = chunk.artifact.artifactId;
45	          const existing = this.artifacts.get(id);
46	
47	          if (chunk.append && existing) {
48	            for (const part of chunk.artifact.parts) {
49	              existing.parts.push(structuredClone(part));
50	            }
51	          } else {
52	            this.artifacts.set(id, structuredClone(chunk.artifact));
53	          }
54	
55	          const newText = extractPartsText(chunk.artifact.parts, '');
56	          let chunks = this.artifactChunks.get(id);
57	          if (!chunks) {
58	            chunks = [];
59	            this.artifactChunks.set(id, chunks);
60	          }
61	          if (chunk.append) {
62	            chunks.push(newText);
63	          } else {
64	            chunks.length = 0;
65	            chunks.push(newText);
66	          }
67	        }
68	        break;
69	
70	      case 'task':
71	        this.appendStateInstructions(chunk.status?.state);
72	        this.pushMessage(chunk.status?.message);
73	        if (chunk.artifacts) {
74	          for (const art of chunk.artifacts) {
75	            this.artifacts.set(art.artifactId, structuredClone(art));
76	            this.artifactChunks.set(art.artifactId, [
77	              extractPartsText(art.parts, ''),
78	            ]);
79	          }
80	        }
81	        // History Fallback: Some agent implementations do not populate the
82	        // status.message in their final terminal response, instead archiving
83	        // the final answer in the task's history array. To ensure we don't
84	        // present an empty result, we fallback to the most recent agent message
85	        // in the history only when the task is terminal and no other content
86	        // (message log or artifacts) has been reassembled.
87	        if (
88	          isTerminalState(chunk.status?.state) &&
89	          this.messageLog.length === 0 &&
90	          this.artifacts.size === 0 &&
91	          chunk.history &&
92	          chunk.history.length > 0
93	        ) {
94	          const lastAgentMsg = [...chunk.history]
95	            .reverse()
96	            .find((m) => m.role?.toLowerCase().includes('agent'));
97	          if (lastAgentMsg) {
98	            this.pushMessage(lastAgentMsg);
99	          }
100	        }
101	        break;
102	
103	      case 'message': {
104	        this.pushMessage(chunk);
105	        break;
106	      }
107	
108	      default:
109	        break;
110	    }
111	  }
112	
113	  private appendStateInstructions(state: TaskState | undefined) {
114	    if (state !== 'auth-required') {
115	      return;
116	    }
117	
118	    // Prevent duplicate instructions if multiple chunks report auth-required
119	    if (!this.messageLog.includes(AUTH_REQUIRED_MSG)) {
120	      this.messageLog.push(AUTH_REQUIRED_MSG);
121	    }
122	  }
123	
124	  private pushMessage(message: Message | undefined) {
125	    if (!message) return;
126	    const text = extractPartsText(message.parts, '\n');
127	    if (text && this.messageLog[this.messageLog.length - 1] !== text) {
128	      this.messageLog.push(text);
129	    }
130	  }
131	
132	  /**
133	   * Returns a human-readable string representation of the current reassembled state.
134	   */
135	  toString(): string {
136	    const joinedMessages = this.messageLog.join('\n\n');
137	
138	    const artifactsOutput = Array.from(this.artifacts.keys())
139	      .map((id) => {
140	        const chunks = this.artifactChunks.get(id);
141	        const artifact = this.artifacts.get(id);
142	        if (!chunks || !artifact) return '';
143	        const content = chunks.join('');
144	        const header = artifact.name
145	          ? `Artifact (${artifact.name}):`
146	          : 'Artifact:';
147	        return `${header}\n${content}`;
148	      })
149	      .filter(Boolean)
150	      .join('\n\n');
151	
152	    if (joinedMessages && artifactsOutput) {
153	      return `${joinedMessages}\n\n${artifactsOutput}`;
154	    }
155	    return joinedMessages || artifactsOutput;
156	  }
157	}
158	
159	/**
160	 * Extracts a human-readable text representation from a Message object.
161	 * Handles Text, Data (JSON), and File parts.
162	 */
163	export function extractMessageText(message: Message | undefined): string {
164	  if (!message || !message.parts || !Array.isArray(message.parts)) {
165	    return '';
166	  }
167	
168	  return extractPartsText(message.parts, '\n');
169	}
170	
171	/**
172	 * Extracts text from an array of parts, joining them with the specified separator.
173	 */
174	function extractPartsText(
175	  parts: Part[] | undefined,
176	  separator: string,
177	): string {
178	  if (!parts || parts.length === 0) {
179	    return '';
180	  }
181	  return parts
182	    .map((p) => extractPartText(p))
183	    .filter(Boolean)
184	    .join(separator);
185	}
186	
187	/**
188	 * Extracts text from a single Part.
189	 */
190	function extractPartText(part: Part): string {
191	  if (isTextPart(part)) {
192	    return part.text;
193	  }
194	
195	  if (isDataPart(part)) {
196	    return `Data: ${JSON.stringify(part.data)}`;
197	  }
198	
199	  if (isFilePart(part)) {
200	    const fileData = part.file;
201	    if (fileData.name) {
202	      return `File: ${fileData.name}`;
203	    }
204	    if ('uri' in fileData && fileData.uri) {
205	      return `File: ${fileData.uri}`;
206	    }
207	    return `File: [binary/unnamed]`;
208	  }
209	
210	  return '';
211	}
212	
213	// Type Guards
214	
215	function isTextPart(part: Part): part is TextPart {
216	  return part.kind === 'text';
217	}
218	
219	function isDataPart(part: Part): part is DataPart {
220	  return part.kind === 'data';
221	}
222	
223	function isFilePart(part: Part): part is FilePart {
224	  return part.kind === 'file';
225	}
226	
227	function isStatusUpdateEvent(
228	  result: SendMessageResult,
229	): result is TaskStatusUpdateEvent {
230	  return result.kind === 'status-update';
231	}
232	
233	/**
234	 * Returns true if the given state is a terminal state for a task.
235	 */
236	export function isTerminalState(state: TaskState | undefined): boolean {
237	  return (
238	    state === 'completed' ||
239	    state === 'failed' ||
240	    state === 'canceled' ||
241	    state === 'rejected'
242	  );
243	}
244	
245	/**
246	 * Extracts contextId and taskId from a Message, Task, or Update response.
247	 * Follows the pattern from the A2A CLI sample to maintain conversational continuity.
248	 */
249	export function extractIdsFromResponse(result: SendMessageResult): {
250	  contextId?: string;
251	  taskId?: string;
252	  clearTaskId?: boolean;
253	} {
254	  let contextId: string | undefined;
255	  let taskId: string | undefined;
256	  let clearTaskId = false;
257	
258	  if ('kind'
