30	      expect(isTerminalState('failed')).toBe(true);
31	      expect(isTerminalState('canceled')).toBe(true);
32	      expect(isTerminalState('rejected')).toBe(true);
33	    });
34	
35	    it('should return false for working, submitted, input-required, auth-required, and unknown', () => {
36	      expect(isTerminalState('working')).toBe(false);
37	      expect(isTerminalState('submitted')).toBe(false);
38	      expect(isTerminalState('input-required')).toBe(false);
39	      expect(isTerminalState('auth-required')).toBe(false);
40	      expect(isTerminalState('unknown')).toBe(false);
41	      expect(isTerminalState(undefined)).toBe(false);
42	    });
43	  });
